import java.util.ArrayList;
import java.util.List;

class Solution {
    public boolean canFinish(int numCourses, int[][] prerequisites) {
        List<List<Integer>> graph = new ArrayList<>();
        for (int course = 0; course < numCourses; course++) graph.add(new ArrayList<>());
        for (int[] pair : prerequisites) graph.get(pair[1]).add(pair[0]);
        int[] state = new int[numCourses];
        for (int course = 0; course < numCourses; course++) {
            if (state[course] == 0 && hasCycle(course, graph, state)) return false;
        }
        return true;
    }
    private boolean hasCycle(int course, List<List<Integer>> graph, int[] state) {
        if (state[course] == 1) return true;
        if (state[course] == 2) return false;
        state[course] = 1;
        for (int next : graph.get(course)) if (hasCycle(next, graph, state)) return true;
        state[course] = 2;
        return false;
    }
}

